package com.opensocket.aievent.core.iam.api.response;import com.opensocket.aievent.core.iam.organization.domain.Department;import java.time.Instant;
public record DepartmentResponse(String tenantId,String departmentId,String code,String name,String parentDepartmentId,String managerUserId,String status,int displayOrder,Instant createdAt,Instant updatedAt,long version){public static DepartmentResponse from(Department d){return new DepartmentResponse(d.tenantId().value(),d.departmentId().value(),d.code(),d.name(),d.parentDepartmentId().map(x->x.value()).orElse(""),d.manager().map(x->x.principalId()).orElse(""),d.status().name(),d.displayOrder(),d.createdAt(),d.updatedAt(),d.version());}}
